 def invoke(self,name):return subprocess.run([sys.executable,str(self.entry),'--root',str(self.root),'--source',str(self.source),'--score',str(self.score_path),'--out',str(self.root/name)],capture_output=True,text=True)
 def test_full_audit_and_tampered_count(self):
  good=self.invoke('audit.json');self.assertEqual(good.returncode,0,good.stdout+good.stderr);m=json.loads((self.root/'audit.json').read_text());self.assertEqual(m['selected_iq_predictions_replayed'],1344);self.assertEqual(m['fields_recomputed'],544);self.score['results']['RX8']['all_impaired']['consensus']['pseudo_correct']+=1;self.score_path.write_text(json.dumps(self.score));self.assertNotEqual(self.invoke('bad.json').returncode,0)
 def test_changed_selected_iq_rejected_even_after_rehash(self):
  path=self.source/'source_predictions.npz'
  with np.load(path,allow_pickle=False) as z:data={k:z[k].copy() for k in z.files}
  data['selected_waveforms'][1,0,0,0]=(data['selected_waveforms'][1,0,0,0]+1)%6;np.savez(path,**data);h=hashlib.sha256(path.read_bytes()).hexdigest();manifest_path=self.source/'prediction_complete.json';manifest=json.loads(manifest_path.read_text());manifest['sha256']=h;manifest_path.write_text(json.dumps(manifest));self.score['prediction_sha256']=h;self.score_path.write_text(json.dumps(self.score));result=self.invoke('bad_wave.json');self.assertNotEqual(result.returncode,0);self.assertIn('Replayed selected IQ classification differs',result.stderr)
